  pattern: '动词词干/形容词词干/이다/-았/었/였-/-겠- + -(으)면 + 名词 + 도 + 动词词干 + -ㄹ/을 수 있고 + 名词 + 도 + 动词词干 + -ㄹ/을 수 있다',
