// 按 book 归类（为将来多本书预留；现在只有一本）
export const GRAMMAR_BOOKS: Record<string, GrammarEntry[]> = GRAMMAR_BOOK.reduce(
  (acc, e) => { (acc[e.book] = acc[e.book] || []).push(e); return acc; },
  {} as Record<string, GrammarEntry[]>,
);
